async function sha256(value:string){const digest=await crypto.subtle.digest("SHA-256",new TextEncoder().encode(value));return Array.from(new Uint8Array(digest),b=>b.toString(16).padStart(2,"0")).join("");}
function normalizeCode(v:string){return v.trim().replace(/\s+/g,"").toUpperCase();}
const addressSchema=z.object({name:z.string().trim().min(1).max(120),line1:z.string().trim().min(1).max(180),line2:z.string().trim().max(180).default(""),city:z.string().trim().min(1).max(120),state:z.string().trim().max(120).default(""),postalCode:z.string().trim().min(1).max(30),country:z.string().trim().regex(/^[A-Za-z]{2}$/).transform(x=>x.toUpperCase())});
function moneySplit(total:number,weights:number[]){if(total<=0)return weights.map(()=>0);const sum=weights.reduce((a,b)=>a+b,0);if(!sum)return weights.map(()=>0);const raw=weights.map(w=>total*w/sum),out=raw.map(Math.floor);let left=total-out.reduce((a,b)=>a+b,0);raw.map((x,i)=>({i,f:x-Math.floor(x)})).sort((a,b)=>b.f-a.f).forEach(x=>{if(left-->0)out[x.i]++;});return out;}

async function cartPricing(db:CatalogDB,userId:string,territory:string){
  const snap=await cartSnapshot(db,userId,territory);if(!snap.items.length)throw new ApiError(409,"Your cart is empty.");
  const bad=snap.items.filter((x:any)=>!x.available||!x.offer||!x.book?.productId);if(bad.length)throw new ApiError(409,"One or more cart items are no longer available in your storefront. Remove them before checkout.");
  const currencies=new Set(snap.items.map((x:any)=>String(x.offer.currency).toUpperCase()));if(currencies.size!==1)throw new ApiError(409,"All items in an order must use the same currency.");
  const currency=[...currencies][0];
  const items=[] as any[];for(const x of snap.items as any[]){await assertPreorderPurchaseAllowed(db,userId,String(x.book.productId));const d=await resolvePricingDecision(db,String(x.book.productId),territory,{userId,persist:true});if(!d)throw new ApiError(409,"A cart item is no longer purchasable in your storefront.");items.push({productId:String(x.book.productId),externalId:String(x.book.sourceExternalId||x.book.id),title:String(x.book.title),sku:String(x.book.sku||x.book.productId),offerId:d.offerId,pricingDecisionId:d.id||null,rightsDecisionId:d.rights.decisionId||null,rightsGrantId:d.rights.grantId,rightsSnapshot:{grantId:d.rights.grantId,editionId:d.rights.editionId,territory:d.rights.territory,format:d.rights.format,salesChannel:d.rights.salesChannel,rightsholderName:d.rights.rightsholderName,licenseType:d.rights.licenseType,contractId:d.rights.contractId,contractVersionId:d.rights.contractVersionId,contractPolicy:d.rights.contractPolicy,contractReference:d.rights.contractReference,exclusivity:d.rights.exclusivity,scopeSummary:d.rights.scopeSummary,languageRights:d.rights.languageRights,sourceEvidenceId:d.rights.sourceEvidenceId,drmRequirement:d.rights.drmRequirement,promotionRestrictions:d.rights.promotionRestrictions,startsAt:d.rights.startsAt,endsAt:d.rights.endsAt},amountMinor:Number(d.amountMinor),listAmountMinor:Number(d.listAmountMinor),currency:d.currency,promotionCampaignId:d.promotion?.campaignId||null,pricingPromotion:d.promotion||null,sourceSurface:String(x.sourceSurface||"cart"),sourceRequestId:x.sourceRequestId||null,taxBehavior:d.taxBehavior,taxCode:d.taxCode});}
  const finalCurrencies=new Set(items.map(x=>x.currency));if(finalCurrencies.size!==1)throw new ApiError(409,"All items in an order must resolve to the same currency.");const resolvedCurrency=[...finalCurrencies][0];
  const fingerprint=await sha256(JSON.stringify(items.map(x=>[x.productId,x.offerId,x.amountMinor,x.currency,x.taxBehavior,x.taxCode,x.rightsGrantId,x.rightsSnapshot?.endsAt||null,x.rightsSnapshot?.contractId||null,x.rightsSnapshot?.contractVersionId||null,x.rightsSnapshot?.contractPolicy||{},x.rightsSnapshot?.scopeSummary||"",x.rightsSnapshot?.languageRights||{},x.rightsSnapshot?.sourceEvidenceId||null,x.rightsSnapshot?.drmRequirement||"none",x.rightsSnapshot?.promotionRestrictions||{}])));return{items,currency:resolvedCurrency,subtotalMinor:items.reduce((s,x)=>s+x.amountMinor,0),fingerprint,stalePrice:snap.items.some((x:any)=>x.stalePrice)};
}

async function promoFor(db:CatalogDB,userId:string,code:string,subtotal:number,currency:string){if(!code)return null;const hash=await sha256(normalizeCode(code)),at=now();const row=await db.prepare(`SELECT * FROM commerce_promo_codes WHERE code_hash=? AND active=1 AND (starts_at IS NULL OR starts_at<=?) AND (ends_at IS NULL OR ends_at>?)`).bind(hash,at,at).first<any>();if(!row)throw new ApiError(400,"That promotional code is invalid or expired.");if(row.currency&&String(row.currency).toUpperCase()!==currency)throw new ApiError(400,"That promotional code does not apply to this currency.");if(subtotal<Number(row.minimum_subtotal_minor||0))throw new ApiError(400,"Your cart does not meet this promotion's minimum purchase amount.");const total=Number((await db.prepare("SELECT COUNT(*) n FROM commerce_promo_redemptions WHERE code_hash=? AND status IN ('reserved','applied')").bind(hash).first<any>())?.n||0),mine=Number((await db.prepare("SELECT COUNT(*) n FROM commerce_promo_redemptions WHERE code_hash=? AND user_id=? AND status IN ('reserved','applied')").bind(hash,userId).first<any>())?.n||0);if(row.max_redemptions!=null&&total>=Number(row.max_redemptions))throw new ApiError(409,"That promotion has reached its redemption limit.");if(mine>=Number(row.max_per_user||1))throw new ApiError(409,"You have already used that promotion.");let amount=row.kind==="percent"?Math.floor(subtotal*Math.min(100,Number(row.value))/100):Math.min(subtotal,Number(row.value));let eligibleProducts:string[]=[];try{eligibleProducts=JSON.parse(String(row.eligible_products_json||"[]"));}catch{}return{hash,label:String(row.code_label),amountMinor:Math.max(0,amount),campaignId:row.campaign_id||null,fundingSource:String(row.funding_source||"fore"),publisherFundingBps:Number(row.publisher_funding_bps||0),eligibleProducts,stackable:Number(row.stackable||0)===1,kind:String(row.kind),value:Number(row.value)};}
async function giftAvailability(db:CatalogDB,code:string,currency:string){if(!code)return null;const normalized=normalizeCode(code),hash=await sha256(normalized),at=now();const row=await db.prepare(`SELECT * FROM commerce_gift_cards WHERE code_hash=? AND status='active' AND (expires_at IS NULL OR expires_at>?)`).bind(hash,at).first<any>();if(!row)throw new ApiError(400,"That Cove gift card is invalid or unavailable.");if(String(row.currency).toUpperCase()!==currency)throw new ApiError(400,"That gift card uses a different currency.");const reserved=Number((await db.prepare("SELECT COALESCE(SUM(amount_minor),0) n FROM commerce_balance_reservations WHERE source_type='gift_card' AND source_key=? AND status='reserved'").bind(hash).first<any>())?.n||0);return{hash,last4:String(row.last4),available:Math.max(0,Number(row.balance_minor)-reserved)};}
