  const territory=input.billingAddress.country.toUpperCase();
  if(input.territory.toUpperCase()!==territory)throw new ApiError(400,"Checkout territory must match the billing country used for tax and payment.");
  const db=env.DB,cart=await cartPricing(db,user.id,territory);
  const promo=await promoFor(db,user.id,input.promoCode,cart.subtotalMinor,cart.currency);
  const eligibleSet=new Set<string>((promo?.eligibleProducts||[]).map(String));
  const eligibleWeights=cart.items.map(x=>(!promo||eligibleSet.size===0||eligibleSet.has(String(x.productId)))?Number(x.amountMinor):0);
  const eligibleSubtotal=eligibleWeights.reduce((a,b)=>a+b,0);
