    const taxLines=Array.isArray(tax.line_items?.data)?tax.line_items.data:[];taxLineSnapshot=taxLines.map((line:any)=>({reference:line.reference||"",amount:Number(line.amount||0),amountTax:Number(line.amount_tax||line.tax_amount||0),taxBehavior:line.tax_behavior||""}));
    if(taxLines.length===discounted.length){const taxByRef=new Map<string,number>();for(const line of taxLines){taxByRef.set(String(line.reference||""),Number(line.amount_tax||line.tax_amount||0));}discounted.forEach((item,i)=>{item.taxMinor=taxByRef.get(`${item.productId}:${i}`)||0;});}
    else{const exclusiveIdx=discounted.map((x,i)=>({x,i})).filter(v=>v.x.taxBehavior!=="inclusive"),inclusiveIdx=discounted.map((x,i)=>({x,i})).filter(v=>v.x.taxBehavior==="inclusive"),exclusiveShares=moneySplit(taxMinor,exclusiveIdx.map(v=>v.x.taxableMinor)),inclusiveShares=moneySplit(taxInclusiveMinor,inclusiveIdx.map(v=>v.x.taxableMinor));exclusiveIdx.forEach((v,j)=>{discounted[v.i].taxMinor=exclusiveShares[j]||0});inclusiveIdx.forEach((v,j)=>{discounted[v.i].taxMinor=inclusiveShares[j]||0});}
