  const gift=await giftAvailability(db,input.giftCardCode,cart.currency),storeAvailable=input.useStoreCredit?await storeCreditAvailable(db,user.id,cart.currency):0;
  let giftUse=Math.min(total,gift?.available||0),storeUse=Math.min(Math.max(0,total-giftUse),storeAvailable),stripeDue=Math.max(0,total-giftUse-storeUse),minimum=Math.max(0,Number(env.STRIPE_MINIMUM_CHARGE_MINOR||50));
