  await db.prepare(`INSERT INTO commerce_checkout_quotes(id,user_id,cart_id,cart_fingerprint,territory_code,currency,items_json,billing_address_json,subtotal_minor,promo_discount_minor,tax_minor,tax_inclusive_minor,gift_card_minor,store_credit_minor,total_minor,stripe_due_minor,promo_code_hash,gift_card_hash,stripe_tax_calculation_id,tax_breakdown_json,expires_at,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind(id,user.id,cartRow.id,cart.fingerprint,territory,cart.currency,JSON.stringify(items),JSON.stringify(input.billingAddress),cart.subtotalMinor,discount,taxMinor,taxInclusiveMinor,giftUse,storeUse,total,stripeDue,promo?.hash||null,gift?.hash||null,taxId,JSON.stringify(taxBreakdown),expires,at).run();
