  for(const item of items){const lineTax=Number(item.taxMinor||0),exclusiveTax=String(item.taxBehavior||"exclusive")==="exclusive"?lineTax:0,lineTotal=Math.max(0,Number(item.amountMinor)-Number(item.discountMinor||0)+exclusiveTax);await db.prepare(`INSERT INTO commerce_order_items(id,order_id,product_id,offer_id,title_snapshot,sku_snapshot,unit_amount_minor,discount_minor,tax_minor,total_minor,source_surface,source_request_id,pricing_decision_id,rights_decision_id,rights_grant_id,rights_snapshot_json,sales_channel,fulfillment_type,fulfillment_status,promotion_campaign_id,publisher_discount_funding_minor,fore_discount_funding_minor,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,'immediate','pending',?,?,?,?)`).bind(`oi_${crypto.randomUUID()}`,orderId,item.productId,item.offerId,item.title,item.sku||item.productId,item.amountMinor,item.discountMinor||0,lineTax,lineTotal,item.sourceSurface||"cart",item.sourceRequestId||null,item.pricingDecisionId||null,item.rightsDecisionId||null,item.rightsGrantId||null,JSON.stringify(item.rightsSnapshot||{}),item.rightsSnapshot?.salesChannel||"retail",item.checkoutPromotionCampaignId||item.promotionCampaignId||null,item.publisherDiscountFundingMinor||0,item.foreDiscountFundingMinor||0,at).run();}
  for(const item of items){await recordRetailEvent(db,user.id,{eventType:"checkout_started",productId:String(item.productId),externalBookId:String(item.externalId||""),sourceSurface:String(item.sourceSurface||"checkout"),sourceRequestId:item.sourceRequestId||null,territory:String(order.territory_code||"US"),currency:String(order.currency),amountMinor:Number(item.amountMinor||0)-Number(item.discountMinor||0),properties:{orderId,quoteId:quote.id},dedupeKey:`checkout:${orderId}:${item.productId}`});}
  const risk=await assessBuyerOrderRisk(db,orderId);if(risk.action==="block"||(risk.action==="hold"&&order.stripe_due_minor===0)){await db.prepare("UPDATE commerce_orders SET status='canceled',canceled_at=?,failure_code='RISK_BLOCK',failure_message='Checkout requires fraud review.',updated_at=? WHERE id=?").bind(now(),now(),orderId).run();throw new ApiError(403,"This checkout requires manual verification before it can be completed.");}if(risk.action==="hold"){captureMethod="manual";await db.prepare("UPDATE commerce_orders SET capture_method='manual',updated_at=? WHERE id=?").bind(now(),orderId).run();}
