export async function invoiceHtml(db:CatalogDB,userId:string,orderId:string){const x:any=await invoiceRecord(db,userId,orderId),money=(n:number)=>{try{return new Intl.NumberFormat("en-US",{style:"currency",currency:x.currency}).format(Number(n||0)/100)}catch{return `${x.currency} ${(Number(n||0)/100).toFixed(2)}`}},a=x.billingAddress||{},items=(x.items||[]).map((i:any)=>`<tr><td>${htmlEscape(i.title_snapshot)}</td><td>${htmlEscape(i.sku_snapshot)}</td><td class="num">${htmlEscape(money(i.unit_amount_minor))}</td><td class="num">-${htmlEscape(money(i.discount_minor))}</td><td class="num">${htmlEscape(money(i.tax_minor))}</td><td class="num">${htmlEscape(money(i.total_minor))}</td></tr>`).join("");return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>${htmlEscape(x.invoiceNumber)} · Cove</title><style>body{font-family:ui-sans-serif,system-ui,sans-serif;color:#17202b;margin:0;background:#f5f3ee}.sheet{max-width:900px;margin:32px auto;background:#fff;padding:48px;box-shadow:0 8px 35px #0001}.top{display:flex;justify-content:space-between;gap:24px}.brand{font-family:Georgia,serif;font-size:34px}.muted{color:#687381}.address{line-height:1.5}.meta{text-align:right}.meta strong{display:block;font-size:20px;margin-bottom:5px}table{width:100%;border-collapse:collapse;margin:35px 0 20px;font-size:13px}th,td{padding:10px 8px;border-bottom:1px solid #dfe3e7;text-align:left}.num{text-align:right;white-space:nowrap}.totals{max-width:370px;margin-left:auto}.row{display:flex;justify-content:space-between;padding:6px 0}.total{font-size:18px;font-weight:700;border-top:2px solid #17202b;margin-top:8px;padding-top:12px}.print{margin-top:28px}@media print{body{background:#fff}.sheet{box-shadow:none;margin:0;max-width:none}.print{display:none}}</style></head><body><main class="sheet"><div class="top"><div><div class="brand">fore.</div><p class="muted">Digital bookstore receipt / invoice record</p></div><div class="meta"><strong>${htmlEscape(x.invoiceNumber)}</strong><span>${htmlEscape(new Date(x.issuedAt).toLocaleString("en-US",{dateStyle:"long"}))}</span><br><span>Order ${htmlEscape(x.orderId)}</span></div></div><section><h3>Bill to</h3><div class="address">${htmlEscape(a.name)}<br>${htmlEscape(a.line1)}${a.line2?`<br>${htmlEscape(a.line2)}`:""}<br>${htmlEscape(a.city)}${a.state?`, ${htmlEscape(a.state)}`:""} ${htmlEscape(a.postalCode)}<br>${htmlEscape(a.country)}</div></section><table><thead><tr><th>Title</th><th>SKU</th><th class="num">Price</th><th class="num">Discount</th><th class="num">Tax</th><th class="num">Total</th></tr></thead><tbody>${items}</tbody></table><div class="totals"><div class="row"><span>Subtotal</span><strong>${htmlEscape(money(x.subtotalMinor))}</strong></div>${x.discountMinor?`<div class="row"><span>Promotion</span><strong>-${htmlEscape(money(x.discountMinor))}</strong></div>`:""}<div class="row"><span>Tax added</span><strong>${htmlEscape(money(x.taxMinor))}</strong></div>${x.taxInclusiveMinor?`<div class="row"><span>Tax included in item prices</span><strong>${htmlEscape(money(x.taxInclusiveMinor))}</strong></div>`:""}<div class="row total"><span>Total</span><strong>${htmlEscape(money(x.totalMinor))}</strong></div>${x.refundedMinor?`<div class="row"><span>Refunded</span><strong>-${htmlEscape(money(x.refundedMinor))}</strong></div>`:""}</div><p class="muted">This document reflects Cove's immutable order record. Stripe payment receipts remain available separately when a Stripe payment method was used.</p><p class="print muted">Use your browser’s Print command to print or save this invoice as PDF.</p></main></body></html>`;}

export async function captureAuthorizedOrder(env:CoveEnv,orderId:string){const o=await env.DB.prepare("SELECT * FROM commerce_orders WHERE id=?").bind(orderId).first<any>();if(!o||!o.stripe_payment_intent_id)throw new ApiError(404,"Authorized payment not found.");if(o.status!=="authorized")throw new ApiError(409,"This order is not awaiting capture.");const pi=await stripeRequest(env,`payment_intents/${encodeURIComponent(o.stripe_payment_intent_id)}/capture`,{idempotencyKey:`fore-capture-${orderId}`});if(pi.status==="succeeded")await finalizePaidOrder(env,orderId,{provider:"stripe",paymentIntentId:pi.id,chargeId:typeof pi.latest_charge==="string"?pi.latest_charge:null,receiptUrl:null});return{orderId,status:pi.status};}

export async function refundOrder(env:CoveEnv,raw:unknown){
  const input=z.object({orderId:z.string().min(8).max(120),amountMinor:z.number().int().positive().optional(),reason:z.string().max(500).default("requested_by_customer"),idempotencyKey:z.string().min(16).max(200)}).parse(raw),db=env.DB;
  const existing=await db.prepare("SELECT * FROM commerce_refunds WHERE idempotency_key=?").bind(input.idempotencyKey).first<any>();
  if(existing)return{id:existing.id,providerRefundId:existing.provider_refund_id||null,status:existing.status,amountMinor:Number(existing.amount_minor),stripeAmountMinor:Number(existing.stripe_amount_minor||0),giftCardAmountMinor:Number(existing.gift_card_amount_minor||0),storeCreditAmountMinor:Number(existing.store_credit_amount_minor||0)};
  const o=await db.prepare("SELECT * FROM commerce_orders WHERE id=?").bind(input.orderId).first<any>();
  if(!o||!["paid","partially_refunded","disputed"].includes(o.status))throw new ApiError(409,"This order is not refundable.");
  const committed=await db.prepare(`SELECT COALESCE(SUM(amount_minor),0) amount,COALESCE(SUM(stripe_amount_minor),0) stripe,COALESCE(SUM(gift_card_amount_minor),0) gift,COALESCE(SUM(store_credit_amount_minor),0) store FROM commerce_refunds WHERE order_id=? AND status IN ('pending','succeeded')`).bind(o.id).first<any>();
  const remainingTotal=Math.max(0,Number(o.total_minor)-Number(committed?.amount||0));
  const amount=Math.min(input.amountMinor||remainingTotal,remainingTotal);if(amount<=0)throw new ApiError(409,"This order has already been fully refunded or has a refund in progress.");
  let left=amount;
  const stripeAvailable=Math.max(0,Number(o.stripe_due_minor)-Number(committed?.stripe||0)),stripeAmount=Math.min(left,stripeAvailable);left-=stripeAmount;
  const storeAvailable=Math.max(0,Number(o.store_credit_minor)-Number(committed?.store||0)),storeAmount=Math.min(left,storeAvailable);left-=storeAmount;
  const giftAvailable=Math.max(0,Number(o.gift_card_minor)-Number(committed?.gift||0)),giftAmount=Math.min(left,giftAvailable);left-=giftAmount;
  if(left>0)throw new ApiError(409,"The original payment tenders cannot cover that refund amount.");
  if(stripeAmount>0&&!o.stripe_payment_intent_id)throw new ApiError(409,"Stripe payment information is missing for this order.");
  const id=`ref_${crypto.randomUUID()}`,at=now();
  await db.prepare("INSERT INTO commerce_refunds(id,order_id,amount_minor,stripe_amount_minor,gift_card_amount_minor,store_credit_amount_minor,currency,reason,status,idempotency_key,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?, 'pending',?,?,?)").bind(id,o.id,amount,stripeAmount,giftAmount,storeAmount,o.currency,input.reason,input.idempotencyKey,at,at).run();
  if(stripeAmount===0){await applyRefundSuccess(env,id,{id:`internal_${id}`});return{id,providerRefundId:null,status:"succeeded",amountMinor:amount,stripeAmountMinor:0,giftCardAmountMinor:giftAmount,storeCreditAmountMinor:storeAmount};}
  try{
    const refund=await stripeRequest(env,"refunds",{idempotencyKey:input.idempotencyKey,params:{payment_intent:o.stripe_payment_intent_id,amount:stripeAmount,reason:["duplicate","fraudulent","requested_by_customer"].includes(input.reason)?input.reason:"requested_by_customer",metadata:{fore_order_id:o.id,fore_refund_id:id,fore_total_refund_minor:amount}}});
    await db.prepare("UPDATE commerce_refunds SET provider_refund_id=?,status=?,updated_at=? WHERE id=?").bind(refund.id,refund.status||"pending",now(),id).run();
    if(refund.status==="succeeded")await applyRefundSuccess(env,id,refund);
    return{id,providerRefundId:refund.id,status:refund.status,amountMinor:amount,stripeAmountMinor:stripeAmount,giftCardAmountMinor:giftAmount,storeCreditAmountMinor:storeAmount};
  }catch(e){await db.prepare("UPDATE commerce_refunds SET status='failed',updated_at=? WHERE id=?").bind(now(),id).run();throw e;}
}

async function applyRefundSuccess(env:CoveEnv,refundId:string,refundPayload:any){
  const db=env.DB,r=await db.prepare("SELECT * FROM commerce_refunds WHERE id=?").bind(refundId).first<any>();if(!r||r.succeeded_at)return;
  const o=await db.prepare("SELECT * FROM commerce_orders WHERE id=?").bind(r.order_id).first<any>();if(!o)throw new ApiError(404,"Refund order not found.");
  const at=now(),previousRefunded=Number(o.refunded_minor||0),refundAmount=Number(r.amount_minor),newRefunded=Math.min(Number(o.total_minor),previousRefunded+refundAmount),full=newRefunded>=Number(o.total_minor);
  const giftAmount=Number(r.gift_card_amount_minor||0),storeAmount=Number(r.store_credit_amount_minor||0),stripeAmount=Number(r.stripe_amount_minor||0);
  if(giftAmount>0){
    const reservation=await db.prepare("SELECT source_key FROM commerce_balance_reservations WHERE order_id=? AND source_type='gift_card' AND status='consumed' LIMIT 1").bind(o.id).first<any>();
    if(!reservation?.source_key)throw new ApiError(500,"The original gift-card tender could not be restored.");
    const card=await db.prepare("SELECT balance_minor,status,expires_at FROM commerce_gift_cards WHERE code_hash=?").bind(reservation.source_key).first<any>();if(!card)throw new ApiError(500,"The original gift card no longer exists.");
    const after=Number(card.balance_minor)+giftAmount;
    await db.prepare("UPDATE commerce_gift_cards SET balance_minor=?,status=CASE WHEN status='exhausted' AND (expires_at IS NULL OR expires_at>?) THEN 'active' ELSE status END,updated_at=? WHERE code_hash=?").bind(after,at,at,reservation.source_key).run();
    await db.prepare("INSERT INTO commerce_gift_card_ledger(id,code_hash,order_id,entry_type,amount_minor,balance_after_minor,created_at) VALUES(?,?,?,'refund',?,?,?)").bind(crypto.randomUUID(),reservation.source_key,o.id,giftAmount,after,at).run();
  }
  if(storeAmount>0)await db.prepare("INSERT INTO commerce_store_credit_ledger(id,user_id,order_id,entry_type,amount_minor,currency,reference,created_at) VALUES(?,?,?,'refund',?,?,?,?)").bind(crypto.randomUUID(),o.user_id,o.id,storeAmount,o.currency,`refund:${r.id}`,at).run();
  await db.prepare("UPDATE commerce_refunds SET status='succeeded',succeeded_at=?,updated_at=? WHERE id=?").bind(at,at,r.id).run();
  try{await reverseRoyaltiesForRefund(db,r.id);}catch(e){console.error("Royalty reversal failed",e);}
  await db.prepare("UPDATE commerce_orders SET refunded_minor=?,status=?,updated_at=? WHERE id=?").bind(newRefunded,full?"refunded":"partially_refunded",at,o.id).run();
  const refundItems=await db.prepare("SELECT id,product_id,total_minor,source_surface,source_request_id FROM commerce_order_items WHERE order_id=? ORDER BY id").bind(o.id).all<any>();
  const refundShares=moneySplit(refundAmount,refundItems.results.map((item:any)=>Math.max(0,Number(item.total_minor||0))));
  for(let i=0;i<refundItems.results.length;i++){const item=refundItems.results[i],share=refundShares[i]||0;if(share<=0)continue;await recordRetailEvent(db,o.user_id,{eventType:"refund_completed",productId:String(item.product_id),sourceSurface:String(item.source_surface||"refund"),sourceRequestId:item.source_request_id||null,territory:String(o.territory_code||"US"),currency:String(o.currency),amountMinor:-share,quantity:-1,properties:{orderId:o.id,orderItemId:item.id,refundId:r.id,fullOrderRefund:full},dedupeKey:`refund:${r.id}:${item.id}`});}
  const totalTax=Number(o.tax_minor||0)+Number(o.tax_inclusive_minor||0),targetTax=Math.round(totalTax*newRefunded/Math.max(1,Number(o.total_minor))),priorTargetTax=Math.round(totalTax*previousRefunded/Math.max(1,Number(o.total_minor))),taxRefund=Math.max(0,targetTax-priorTargetTax),salesRefund=Math.max(0,refundAmount-taxRefund);
  if(salesRefund)await ledger(db,o.id,o.user_id,"refund","sales_returns",salesRefund,o.currency,r.id,{refundId:r.id});
  if(taxRefund)await ledger(db,o.id,o.user_id,"tax_refund","tax_payable",taxRefund,o.currency,r.id,{refundId:r.id});
  if(stripeAmount)await ledger(db,o.id,o.user_id,"refund_tender","stripe_receivable",-stripeAmount,o.currency,r.id,{refundId:r.id});
  if(giftAmount)await ledger(db,o.id,o.user_id,"refund_tender","gift_card_liability",-giftAmount,o.currency,r.id,{refundId:r.id});
  if(storeAmount)await ledger(db,o.id,o.user_id,"refund_tender","store_credit_liability",-storeAmount,o.currency,r.id,{refundId:r.id});
  if(full){
    await db.prepare("UPDATE entitlements SET status='revoked',updated_at=? WHERE user_id=? AND order_item_id IN (SELECT id FROM commerce_order_items WHERE order_id=?) AND entitlement_type='purchase'").bind(at,o.user_id,o.id).run();
    await db.prepare("UPDATE commerce_order_items SET entitlement_status='revoked' WHERE order_id=?").bind(o.id).run();
    await db.prepare("UPDATE preorders SET status='refunded',updated_at=? WHERE order_id=? AND status NOT IN ('released','refunded')").bind(at,o.id).run();
    const promo=await db.prepare("SELECT id,code_hash,status FROM commerce_promo_redemptions WHERE order_id=? LIMIT 1").bind(o.id).first<any>();
    if(promo&&promo.status==="applied"){await db.prepare("UPDATE commerce_promo_redemptions SET status='refunded',updated_at=? WHERE id=?").bind(at,promo.id).run();await db.prepare("UPDATE commerce_promo_codes SET redemptions=MAX(0,redemptions-1),updated_at=? WHERE code_hash=?").bind(at,promo.code_hash).run();}
  }
  try{const ratio=Math.min(1,refundAmount/Math.max(1,Number(o.total_minor))),items=(await db.prepare(`SELECT oi.*,pd.promotion_amount_minor,pr.campaign_id pricing_campaign_id FROM commerce_order_items oi LEFT JOIN pricing_decisions pd ON pd.id=oi.pricing_decision_id LEFT JOIN promotions pr ON pr.id=pd.promotion_id WHERE oi.order_id=?`).bind(o.id).all<any>()).results;for(const item of items){const maps=new Map<string,number>();if(item.promotion_campaign_id)maps.set(String(item.promotion_campaign_id),Math.round((Number(item.publisher_discount_funding_minor||0)+Number(item.fore_discount_funding_minor||0))*ratio));if(item.pricing_campaign_id)maps.set(String(item.pricing_campaign_id),(maps.get(String(item.pricing_campaign_id))||0)+Math.round(Number(item.promotion_amount_minor||0)*ratio));for(const [campaignId,fundingMinor] of maps)await recordPromotionAttribution(db,{campaignId,productId:item.product_id,userId:o.user_id,eventType:"refund",orderId:o.id,orderItemId:item.id,amountMinor:Math.round(Number(item.total_minor||0)*ratio),fundingMinor,currency:o.currency,sourceSurface:"refund",dedupeKey:`refund:${r.id}:${item.id}:${campaignId}`});}}catch(e){console.error("Promotion refund attribution failed",e);}
  if(o.stripe_tax_transaction_id&&!r.tax_reversal_id&&refundAmount>0){try{const rev=await stripeRequest(env,"tax/transactions/create_reversal",{idempotencyKey:`fore-tax-reversal-${r.id}`,params:{original_transaction:o.stripe_tax_transaction_id,mode:full?"full":"partial",reference:`${o.id}-${r.id}`,...(full?{}:{flat_amount:-refundAmount}),metadata:{fore_order_id:o.id,fore_refund_id:r.id}}});await db.prepare("UPDATE commerce_refunds SET tax_reversal_id=?,updated_at=? WHERE id=?").bind(rev.id,now(),r.id).run();await recordCustomerTaxReversal(db,r.id,String(rev.id),refundAmount,{mode:full?"full":"partial"});}catch(e){console.error("Stripe Tax reversal failed",e);}}
}

function hexToBytes(hex:string){if(hex.length%2)return new Uint8Array();const out=new Uint8Array(hex.length/2);for(let i=0;i<out.length;i++)out[i]=parseInt(hex.slice(i*2,i*2+2),16);return out;}
function constantEqual(a:Uint8Array,b:Uint8Array){if(a.length!==b.length)return false;let diff=0;for(let i=0;i<a.length;i++)diff|=a[i]^b[i];return diff===0;}
async function verifyStripeSignature(raw:string,header:string,secret:string){const parts=header.split(",").map(x=>x.split("=")),timestamp=parts.find(x=>x[0]==="t")?.[1],signatures=parts.filter(x=>x[0]==="v1").map(x=>x[1]);if(!timestamp||!signatures.length)return false;const t=Number(timestamp);if(!Number.isFinite(t)||Math.abs(Date.now()/1000-t)>300)return false;const key=await crypto.subtle.importKey("raw",new TextEncoder().encode(secret),{name:"HMAC",hash:"SHA-256"},false,["sign"]),sig=new Uint8Array(await crypto.subtle.sign("HMAC",key,new TextEncoder().encode(`${timestamp}.${raw}`)));return signatures.some(x=>constantEqual(sig,hexToBytes(x)));}
export async function stripeWebhook(env:CoveEnv,request:Request){const secret=String(env.STRIPE_WEBHOOK_SECRET||"");if(!secret||PLACEHOLDER_RE.test(secret))throw new ApiError(503,"Stripe webhook signing secret is not configured.");const raw=await request.text(),signature=request.headers.get("stripe-signature")||"";if(!(await verifyStripeSignature(raw,signature,secret)))throw new ApiError(400,"Invalid Stripe webhook signature.");const event=JSON.parse(raw),db=env.DB,id=String(event.id||"");if(!id)throw new ApiError(400,"Stripe event ID missing.");const expectedLive=commerceConfig(env).livemode;if(Boolean(event.livemode)!==expectedLive)throw new ApiError(400,`Stripe webhook mode mismatch: expected ${expectedLive?"live":"test"} events.`);if(await db.prepare("SELECT 1 ok FROM commerce_webhook_events WHERE provider_event_id=?").bind(id).first<any>())return{received:true,duplicate:true};const hash=await sha256(raw),at=now();await db.prepare("INSERT INTO commerce_webhook_events(provider_event_id,event_type,livemode,payload_sha256,status,received_at) VALUES(?,?,?,?, 'received',?)").bind(id,event.type,event.livemode?1:0,hash,at).run();try{await processStripeEvent(env,event);await db.prepare("UPDATE commerce_webhook_events SET status='processed',processed_at=? WHERE provider_event_id=?").bind(now(),id).run();return{received:true};}catch(e){await db.prepare("UPDATE commerce_webhook_events SET status='failed',error=?,processed_at=? WHERE provider_event_id=?").bind(String((e as Error).message||e).slice(0,1000),now(),id).run();throw e;}}
async function orderFromPI(db:CatalogDB,pi:any){const id=pi?.metadata?.fore_order_id;if(id)return db.prepare("SELECT * FROM commerce_orders WHERE id=?").bind(id).first<any>();if(pi?.id)return db.prepare("SELECT * FROM commerce_orders WHERE stripe_payment_intent_id=?").bind(pi.id).first<any>();return null;}
async function processStripeEvent(env:CoveEnv,event:any){const db=env.DB,obj=event.data?.object||{},type=String(event.type||"");if(type==="payment_intent.succeeded"){const o=await orderFromPI(db,obj);if(o){let charge:any=null;if(obj.latest_charge){try{charge=await stripeRequest(env,`charges/${encodeURIComponent(typeof obj.latest_charge==="string"?obj.latest_charge:obj.latest_charge.id)}`,{method:"GET"});}catch{}}if(charge?.outcome)await ingestStripeRiskSignal(db,o.id,charge,String(event.id||charge.id));await finalizePaidOrder(env,o.id,{provider:"stripe",paymentIntentId:obj.id,chargeId:charge?.id||(typeof obj.latest_charge==="string"?obj.latest_charge:null),receiptUrl:charge?.receipt_url||null,paymentMethod:charge?.payment_method_details?.type||"Stripe"});}}else if(type==="payment_intent.amount_capturable_updated"){const o=await orderFromPI(db,obj);if(o)await db.prepare("UPDATE commerce_orders SET status='authorized',authorized_at=?,updated_at=? WHERE id=? AND status NOT IN ('paid','refunded')").bind(now(),now(),o.id).run();}else if(type==="payment_intent.processing"){const o=await orderFromPI(db,obj);if(o)await db.prepare("UPDATE commerce_orders SET status='processing',updated_at=? WHERE id=? AND status='pending_payment'").bind(now(),o.id).run();}else if(type==="payment_intent.payment_failed"){const o=await orderFromPI(db,obj);if(o){await db.prepare("UPDATE commerce_orders SET status='payment_failed',failure_code=?,failure_message=?,updated_at=? WHERE id=? AND status NOT IN ('paid','refunded')").bind(obj.last_payment_error?.code||null,obj.last_payment_error?.message||"Payment failed",now(),o.id).run();try{await emitNotification(db,{userId:String(o.user_id),eventType:"payment_failed",dedupeKey:`payment-failed:${o.id}:${obj.id}`,title:"Payment failed",body:String(obj.last_payment_error?.message||"Your payment method was declined or could not be charged."),urgency:"high",subjectType:"order",subjectId:o.id,actionUrl:`/checkout?order=${encodeURIComponent(o.id)}`,payload:{orderId:o.id,paymentIntentId:obj.id,errorCode:obj.last_payment_error?.code||null}});}catch{}}}else if(type==="payment_intent.canceled"){const o=await orderFromPI(db,obj);if(o){await releaseOrderReservations(db,o.id);await db.prepare("UPDATE commerce_orders SET status='canceled',canceled_at=?,updated_at=? WHERE id=? AND status NOT IN ('paid','refunded')").bind(now(),now(),o.id).run();}}else if(type==="charge.succeeded"){const o=obj.payment_intent?await db.prepare("SELECT * FROM commerce_orders WHERE stripe_payment_intent_id=?").bind(typeof obj.payment_intent==="string"?obj.payment_intent:obj.payment_intent.id).first<any>():null;if(o)await db.prepare("UPDATE commerce_orders SET stripe_charge_id=?,receipt_url=COALESCE(?,receipt_url),risk_level=COALESCE(?,risk_level),risk_score=COALESCE(?,risk_score),updated_at=? WHERE id=?").bind(obj.id,obj.receipt_url||null,obj.outcome?.risk_level||null,obj.outcome?.risk_score??null,now(),o.id).run();}else if(type==="invoice.paid"||type==="invoice.payment_succeeded"){const customer=typeof obj.customer==="string"?obj.customer:obj.customer?.id,user=customer?await db.prepare("SELECT user_id FROM commerce_customers WHERE stripe_customer_id=?").bind(customer).first<any>():null;if(user?.user_id)try{await emitNotification(db,{userId:String(user.user_id),eventType:"subscription_billing",dedupeKey:`subscription-billing:${obj.id}`,title:"Subscription payment received",body:`Your Cove subscription payment of ${String(obj.currency||"usd").toUpperCase()} ${(Number(obj.amount_paid||0)/100).toFixed(2)} was received.`,subjectType:"stripe_invoice",subjectId:String(obj.id),actionUrl:"/account",payload:{invoiceId:obj.id,subscriptionId:typeof obj.subscription==="string"?obj.subscription:obj.subscription?.id||null,currency:String(obj.currency||"usd").toUpperCase(),amountPaidMinor:Number(obj.amount_paid||0),periodStart:obj.period_start||null,periodEnd:obj.period_end||null}});}catch(e){console.error("Subscription billing notification enqueue failed",e);}}else if(type==="invoice.payment_failed"){const customer=typeof obj.customer==="string"?obj.customer:obj.customer?.id,user=customer?await db.prepare("SELECT user_id FROM commerce_customers WHERE stripe_customer_id=?").bind(customer).first<any>():null;if(user?.user_id)try{await emitNotification(db,{userId:String(user.user_id),eventType:"payment_failed",dedupeKey:`subscription-payment-failed:${obj.id}:${Number(obj.attempt_count||0)}`,title:"Subscription payment failed",body:"Cove could not collect your subscription payment. Update your billing method to avoid interruption.",urgency:"high",subjectType:"stripe_invoice",subjectId:String(obj.id),actionUrl:"/account",payload:{invoiceId:obj.id,subscriptionId:typeof obj.subscription==="string"?obj.subscription:obj.subscription?.id||null,attemptCount:Number(obj.attempt_count||0),nextPaymentAttempt:obj.next_payment_attempt||null}});}catch(e){console.error("Subscription payment-failure notification enqueue failed",e);}}else if(type==="refund.updated"||type==="refund.created"){const r=await db.prepare("SELECT * FROM commerce_refunds WHERE provider_refund_id=?").bind(obj.id).first<any>();if(r){await db.prepare("UPDATE commerce_refunds SET status=?,updated_at=? WHERE id=?").bind(obj.status||r.status,now(),r.id).run();if(obj.status==="succeeded")await applyRefundSuccess(env,r.id,obj);}}else if(type.startsWith("charge.dispute.")){await syncDispute(db,obj,type);}}
async function syncDispute(db:CatalogDB,d:any,eventType:string){const charge=String(typeof d.charge==="string"?d.charge:d.charge?.id||""),order=charge?await db.prepare("SELECT * FROM commerce_orders WHERE stripe_charge_id=?").bind(charge).first<any>():null,at=now();await db.prepare(`INSERT INTO commerce_disputes(provider_dispute_id,order_id,charge_id,amount_minor,currency,reason,status,evidence_due_at,created_at,updated_at,closed_at) VALUES(?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(provider_dispute_id) DO UPDATE SET status=excluded.status,reason=excluded.reason,evidence_due_at=excluded.evidence_due_at,updated_at=excluded.updated_at,closed_at=excluded.closed_at`).bind(d.id,order?.id||null,charge,Number(d.amount||0),String(d.currency||"").toUpperCase(),d.reason||"",d.status||"unknown",d.evidence_details?.due_by?new Date(Number(d.evidence_details.due_by)*1000).toISOString():null,at,at,eventType==="charge.dispute.closed"?at:null).run();if(order){const amount=Number(d.amount||0),currency=String(d.currency||order.currency||"").toUpperCase(),ref=String(d.id||charge);
  if(eventType==="charge.dispute.created"){await db.prepare("UPDATE commerce_orders SET status='disputed',updated_at=? WHERE id=?").bind(at,order.id).run();if(amount){await ledger(db,order.id,order.user_id,"dispute_open","dispute_receivable",amount,currency,ref);await ledger(db,order.id,order.user_id,"dispute_open","stripe_receivable",-amount,currency,ref);}}
  if(eventType==="charge.dispute.closed"&&d.status==="lost"){await db.prepare("UPDATE commerce_orders SET status='chargeback_lost',updated_at=? WHERE id=?").bind(at,order.id).run();await db.prepare("UPDATE entitlements SET status='revoked',updated_at=? WHERE user_id=? AND order_item_id IN (SELECT id FROM commerce_order_items WHERE order_id=?) AND entitlement_type='purchase'").bind(at,order.user_id,order.id).run();if(amount){await ledger(db,order.id,order.user_id,"dispute_lost","chargeback_loss",amount,currency,ref);await ledger(db,order.id,order.user_id,"dispute_lost","dispute_receivable",-amount,currency,ref);try{await reverseRoyaltiesForChargeback(db,order.id,ref);}catch(e){console.error("Royalty chargeback reversal failed",e);}}}
  if(eventType==="charge.dispute.closed"&&d.status==="won"){await db.prepare("UPDATE commerce_orders SET status=CASE WHEN refunded_minor>=total_minor THEN 'refunded' WHEN refunded_minor>0 THEN 'partially_refunded' ELSE 'paid' END,updated_at=? WHERE id=?").bind(at,order.id).run();if(amount){await ledger(db,order.id,order.user_id,"dispute_won","stripe_receivable",amount,currency,ref);await ledger(db,order.id,order.user_id,"dispute_won","dispute_receivable",-amount,currency,ref);}}
}}

export async function createPromoCode(db:CatalogDB,raw:unknown){const x=z.object({code:z.string().min(3).max(80),kind:z.enum(["percent","amount"]),value:z.number().int().positive(),currency:z.string().regex(/^[A-Za-z]{3}$/).nullable().optional(),minimumSubtotalMinor:z.number().int().min(0).default(0),maxRedemptions:z.number().int().positive().nullable().optional(),maxPerUser:z.number().int().positive().default(1),startsAt:z.string().datetime().nullable().optional(),endsAt:z.string().datetime().nullable().optional(),active:z.boolean().default(true)}).parse(raw),code=normalizeCode(x.code),hash=await sha256(code),at=now();if(x.kind==="percent"&&x.value>100)throw new ApiError(400,"Percentage discounts cannot exceed 100%.");await db.prepare(`INSERT INTO commerce_promo_codes(code_hash,code_label,kind,value,currency,minimum_subtotal_minor,max_redemptions,max_per_user,active,starts_at,ends_at,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(code_hash) DO UPDATE SET kind=excluded.kind,value=excluded.value,currency=excluded.currency,minimum_subtotal_minor=excluded.minimum_subtotal_minor,max_redemptions=excluded.max_redemptions,max_per_user=excluded.max_per_user,active=excluded.active,starts_at=excluded.starts_at,ends_at=excluded.ends_at,updated_at=excluded.updated_at`).bind(hash,code,x.kind,x.value,x.currency?.toUpperCase()||null,x.minimumSubtotalMinor,x.maxRedemptions||null,x.maxPerUser,x.active?1:0,x.startsAt||null,x.endsAt||null,at,at).run();return{codeLabel:code,active:x.active};}
export async function issueGiftCard(db:CatalogDB,raw:unknown){const x=z.object({currency:z.string().regex(/^[A-Za-z]{3}$/).default("USD"),amountMinor:z.number().int().positive(),expiresAt:z.string().datetime().nullable().optional()}).parse(raw),code=`FORE-${crypto.randomUUID().replace(/-/g,"").slice(0,16).toUpperCase()}`,hash=await sha256(code),at=now();await db.prepare("INSERT INTO commerce_gift_cards(code_hash,last4,currency,original_balance_minor,balance_minor,status,expires_at,created_at,updated_at) VALUES(?,?,?,?,?,'active',?,?,?)").bind(hash,code.slice(-4),x.currency.toUpperCase(),x.amountMinor,x.amountMinor,x.expiresAt||null,at,at).run();return{code,currency:x.currency.toUpperCase(),balanceMinor:x.amountMinor,expiresAt:x.expiresAt||null};}
export async function adjustStoreCredit(db:CatalogDB,raw:unknown){const x=z.object({userId:z.string().min(1).max(180),currency:z.string().regex(/^[A-Za-z]{3}$/).default("USD"),amountMinor:z.number().int().refine(v=>v!==0),reference:z.string().max(300).default("operator adjustment")}).parse(raw),currency=x.currency.toUpperCase();if(x.amountMinor<0){const available=await storeCreditAvailable(db,x.userId,currency);if(available<Math.abs(x.amountMinor))throw new ApiError(409,"Store-credit adjustment would make the balance negative.");}await db.prepare("INSERT INTO commerce_store_credit_ledger(id,user_id,entry_type,amount_minor,currency,reference,created_at) VALUES(?,?,'adjustment',?,?,?,?)").bind(crypto.randomUUID(),x.userId,x.amountMinor,currency,x.reference,now()).run();return{userId:x.userId,currency,balanceMinor:await storeCreditAvailable(db,x.userId,currency)};}

export async function commerceAdminSnapshot(db:CatalogDB){
  const [orders,refunds,disputes,reconciliation,promos,giftCards,ledgerImbalances]=await Promise.all([
    db.prepare("SELECT id,invoice_number,status,currency,total_minor,stripe_due_minor,refunded_minor,risk_level,risk_score,created_at,paid_at FROM commerce_orders ORDER BY created_at DESC LIMIT 100").all<any>(),
    db.prepare("SELECT id,order_id,provider_refund_id,amount_minor,stripe_amount_minor,gift_card_amount_minor,store_credit_amount_minor,currency,reason,status,created_at,succeeded_at FROM commerce_refunds ORDER BY created_at DESC LIMIT 100").all<any>(),
    db.prepare("SELECT provider_dispute_id,order_id,amount_minor,currency,reason,status,evidence_due_at,created_at,updated_at FROM commerce_disputes ORDER BY updated_at DESC LIMIT 100").all<any>(),
    db.prepare("SELECT * FROM commerce_reconciliation_runs ORDER BY started_at DESC LIMIT 25").all<any>(),
    db.prepare("SELECT code_label,kind,value,currency,minimum_subtotal_minor,max_redemptions,max_per_user,redemptions,active,starts_at,ends_at FROM commerce_promo_codes ORDER BY updated_at DESC LIMIT 100").all<any>(),
    db.prepare("SELECT last4,currency,original_balance_minor,balance_minor,status,expires_at,issued_by,created_at FROM commerce_gift_cards ORDER BY created_at DESC LIMIT 100").all<any>(),
    db.prepare("SELECT order_id,currency,SUM(amount_minor) AS balance_minor,COUNT(*) AS entries,MAX(created_at) AS last_posted_at FROM commerce_ledger_entries WHERE order_id IS NOT NULL GROUP BY order_id,currency HAVING SUM(amount_minor)<>0 ORDER BY last_posted_at DESC LIMIT 100").all<any>(),
  ]);
  return{orders:orders.results,refunds:refunds.results,disputes:disputes.results,reconciliation:reconciliation.results,promos:promos.results,giftCards:giftCards.results,ledgerImbalances:ledgerImbalances.results};
}

export async function reconcileStripe(env:CoveEnv,limit=100){const db=env.DB,id=`recon_${crypto.randomUUID()}`,started=now();await db.prepare("INSERT INTO commerce_reconciliation_runs(id,started_at,status) VALUES(?,?,'running')").bind(id,started).run();const rows=await db.prepare("SELECT * FROM commerce_orders WHERE stripe_payment_intent_id IS NOT NULL ORDER BY updated_at DESC LIMIT ?").bind(Math.max(1,Math.min(500,limit))).all<any>();let mismatches=0,repaired=0;const details:any[]=[];for(const o of rows.results){try{const pi=await stripeRequest(env,`payment_intents/${encodeURIComponent(o.stripe_payment_intent_id)}`,{method:"GET",params:{expand:["latest_charge.balance_transaction"]}});const ageMs=Date.now()-Date.parse(String(o.updated_at||o.created_at||0)),staleRecoverable=["pending_payment","payment_failed"].includes(o.status)&&ageMs>24*60*60_000&&["requires_payment_method","requires_confirmation","requires_action","canceled"].includes(String(pi.status));if(staleRecoverable){if(pi.status!=="canceled")await stripeRequest(env,`payment_intents/${encodeURIComponent(o.stripe_payment_intent_id)}/cancel`,{idempotencyKey:`fore-expire-${o.id}`,params:{cancellation_reason:"abandoned"}});await releaseOrderReservations(db,o.id);await db.prepare("UPDATE commerce_orders SET status='canceled',canceled_at=COALESCE(canceled_at,?),updated_at=? WHERE id=?").bind(now(),now(),o.id).run();repaired++;details.push({orderId:o.id,action:"expired_stale_checkout",stripeStatus:pi.status});continue;}const expectedPaid=["paid","partially_refunded","refunded","disputed","chargeback_lost"].includes(o.status),stripePaid=pi.status==="succeeded";if(expectedPaid!==stripePaid&&o.status!=="authorized"){mismatches++;details.push({orderId:o.id,foreStatus:o.status,stripeStatus:pi.status});if(stripePaid){const ch=typeof pi.latest_charge==="object"?pi.latest_charge:null;await finalizePaidOrder(env,o.id,{provider:"stripe",paymentIntentId:pi.id,chargeId:ch?.id||null,receiptUrl:ch?.receipt_url||null,paymentMethod:ch?.payment_method_details?.type});repaired++;}}
      const ch=typeof pi.latest_charge==="object"?pi.latest_charge:null,bt=ch?.balance_transaction;if(bt&&Number(bt.fee||0)>0){const fee=Number(bt.fee),currency=String(bt.currency||o.currency).toUpperCase(),ref=String(bt.id),items=(await db.prepare("SELECT id,total_minor FROM commerce_order_items WHERE order_id=? ORDER BY created_at,id").bind(o.id).all<any>()).results,shares=moneySplit(fee,items.map((i:any)=>Math.max(0,Number(i.total_minor||0))));for(let i=0;i<items.length;i++)await db.prepare("UPDATE commerce_order_items SET processor_fee_minor=? WHERE id=?").bind(shares[i]||0,items[i].id).run();await ledger(db,o.id,o.user_id,"processor_fee","stripe_fee_expense",fee,currency,ref,{net:bt.net});await ledger(db,o.id,o.user_id,"processor_fee","stripe_receivable",-fee,currency,ref,{net:bt.net});try{await accrueRoyaltiesForOrder(db,o.id);}catch(e){details.push({orderId:o.id,royaltyReconciliationError:(e as Error).message});}}if(ch?.receipt_url&&!o.receipt_url)await db.prepare("UPDATE commerce_orders SET receipt_url=?,stripe_charge_id=COALESCE(stripe_charge_id,?),updated_at=? WHERE id=?").bind(ch.receipt_url,ch.id,now(),o.id).run();}catch(e){details.push({orderId:o.id,error:(e as Error).message});}}
  const finished=now();await db.prepare("UPDATE commerce_reconciliation_runs SET finished_at=?,status='complete',checked_orders=?,mismatches=?,repaired=?,details_json=? WHERE id=?").bind(finished,rows.results.length,mismatches,repaired,JSON.stringify(details.slice(0,100)),id).run();return{id,checked:rows.results.length,mismatches,repaired,details};}
export async function accountingCsv(db:CatalogDB,from:string,to:string){const rows=await db.prepare("SELECT * FROM commerce_ledger_entries WHERE created_at>=? AND created_at<? ORDER BY created_at,id").bind(from,to).all<any>(),headers=["created_at","order_id","refund_id","user_id","entry_type","account_code","amount_minor","currency","external_reference","metadata_json"],escape=(v:any)=>`"${String(v??"").replaceAll('"','""')}"`;return[headers.join(","),...rows.results.map(r=>headers.map(h=>escape(r[h])).join(","))].join("\n");}


/**
 * Executes durable preorder-refund jobs through the same refund path used by customer service.
 * Jobs are leased before provider calls and completion is idempotently recorded back on the
 * preorder ledger. A provider failure requeues (or terminally fails) through the job policy.
 */
export async function processPreorderRefundJobs(env: CoveEnv, raw: unknown) {
  const input = z.object({
    workerId: z.string().min(3).max(120).default("fore-preorder-refund-worker"),
    limit: z.number().int().min(1).max(50).default(20),
    leaseSeconds: z.number().int().min(30).max(1800).default(300),
  }).parse(raw ?? {});
  const leased = await leasePreorderRefundJobs(env.DB, input);
  const results: Array<Record<string, unknown>> = [];
  for (const job of leased.jobs as any[]) {
    try {
      const refund = await refundOrder(env, {
        orderId: String(job.order_id),
        amountMinor: Number(job.amount_minor),
        reason: "requested_by_customer",
        idempotencyKey: `preorder-refund-${String(job.id)}-v1`,
      });
      await completePreorderRefundJob(env.DB, {
        jobId: String(job.id),
        leaseToken: String(job.lease_token),
        success: true,
        providerRefundId: refund.providerRefundId || null,
      });
      results.push({ jobId: job.id, status: "succeeded", refundId: refund.id });
    } catch (error) {
      const message = String((error as Error)?.message || error).slice(0, 2000);
      await completePreorderRefundJob(env.DB, {
        jobId: String(job.id),
        leaseToken: String(job.lease_token),
        success: false,
        error: message,
      });
      results.push({ jobId: job.id, status: "failed_or_requeued", error: message });
    }
  }
  return { leased: leased.jobs.length, results };
}

export async function createBillingPortal(env:CoveEnv,user:User,returnUrl:string){
  const customer=await ensureStripeCustomer(env,user);
  const portal=await stripeRequest(env,"billing_portal/sessions",{params:{customer,return_url:returnUrl},idempotencyKey:`fore-billing-portal-${user.id}-${Math.floor(Date.now()/60000)}`});
  if(!portal?.url)throw new ApiError(502,"Stripe billing management is temporarily unavailable.");
  return{url:String(portal.url)};
}

export async function syncCustomerBillingMethods(env:CoveEnv,user:User){
  const customer=await ensureStripeCustomer(env,user),db=env.DB,at=now();
  const cards=await stripeRequest(env,"payment_methods",{method:"GET",params:{customer,type:"card",limit:100}});
  const methods=Array.isArray(cards?.data)?cards.data:[];
  for(const pm of methods){const card=pm.card||{},billing=pm.billing_details||{};await db.prepare(`INSERT INTO account_billing_methods(id,user_id,provider,provider_customer_id,provider_payment_method_id,brand,last4,exp_month,exp_year,billing_name,is_default,status,created_at,updated_at) VALUES(?,?,'stripe',?,?,?,?,?,?,?,0,'active',?,?) ON CONFLICT(provider,provider_payment_method_id) DO UPDATE SET brand=excluded.brand,last4=excluded.last4,exp_month=excluded.exp_month,exp_year=excluded.exp_year,billing_name=excluded.billing_name,status='active',updated_at=excluded.updated_at`).bind(`bill_${crypto.randomUUID()}`,user.id,customer,pm.id,String(card.brand||""),String(card.last4||""),card.exp_month??null,card.exp_year??null,String(billing.name||""),at,at).run();}
  if(methods.length)await db.prepare(`UPDATE account_billing_methods SET status='detached',updated_at=? WHERE user_id=? AND provider='stripe' AND provider_payment_method_id NOT IN (${methods.map(()=>'?').join(',')})`).bind(at,user.id,...methods.map((m:any)=>m.id)).run();
  else await db.prepare("UPDATE account_billing_methods SET status='detached',updated_at=? WHERE user_id=? AND provider='stripe'").bind(at,user.id).run();
  return{synced:methods.length};
}
